-- Refresh product chip arrays from variants
UPDATE public.products p SET
  colors = COALESCE((SELECT array_agg(DISTINCT pv.color ORDER BY pv.color) FROM public.product_variants pv WHERE pv.product_id = p.id AND pv.color IS NOT NULL AND btrim(pv.color) <> ''), p.colors),
  storage = COALESCE((SELECT array_agg(DISTINCT pv.storage ORDER BY pv.storage) FROM public.product_variants pv WHERE pv.product_id = p.id AND pv.storage IS NOT NULL AND btrim(pv.storage) <> ''), p.storage),
  price = COALESCE((SELECT MIN(pv.price) FROM public.product_variants pv WHERE pv.product_id = p.id AND pv.is_active AND pv.price > 0), p.price),
  stock = COALESCE((SELECT SUM(pv.stock) FROM public.product_variants pv WHERE pv.product_id = p.id), p.stock),
  updated_at = NOW()
WHERE p.category = 'iPad'
  AND p.specifications->>'catalog' = 'ipad';

COMMIT;